namespace TaskCapture.Core;
public sealed record Hotkey(uint Modifiers,uint VirtualKey,string Display) {
 public static Hotkey Parse(string text){uint modifiers=0,key=0;List<string> labels=[];var parts=text.Split('+',StringSplitOptions.TrimEntries);if(parts.Length<2)throw new ArgumentException("Используйте Ctrl, Alt или Win вместе с клавишей.");foreach(var part in parts){uint flag=part.ToUpperInvariant() switch{"CTRL"=>2,"ALT"=>1,"SHIFT"=>4,"WIN"=>8,_=>0};if(flag!=0){if(key!=0||(modifiers&flag)!=0)throw new ArgumentException("Некорректное сочетание.");modifiers|=flag;labels.Add(part.ToUpperInvariant() switch{"CTRL"=>"Ctrl","ALT"=>"Alt","SHIFT"=>"Shift",_=>"Win"});}else{if(key!=0)throw new ArgumentException("Укажите одну основную клавишу.");string value=part.ToUpperInvariant();if(value.Length==1&&char.IsAsciiLetterOrDigit(value[0]))key=value[0];else if(value.StartsWith('F')&&int.TryParse(value[1..],out int f)&&f is >=1 and <=11)key=(uint)(111+f);else throw new ArgumentException("Используйте букву, цифру или F1–F11.");labels.Add(value);}}if(key==0||(modifiers&11)==0)throw new ArgumentException("Нужна клавиша с Ctrl, Alt или Win.");return new(modifiers,key,string.Join('+',labels));}
}
